import{_ as e,o as i,c as o,a2 as t}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Constitución Simbiótica: Principios Generales","description":"","frontmatter":{},"headers":[],"relativePath":"es/40-共生宪法总纲.md","filePath":"es/40-共生宪法总纲.md","lastUpdated":null}'),s={name:"es/40-共生宪法总纲.md"};function n(l,a,r,d,c,u){return i(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="constitucion-simbiotica-principios-generales" tabindex="-1">Constitución Simbiótica: Principios Generales <a class="header-anchor" href="#constitucion-simbiotica-principios-generales" aria-label="Permalink to &quot;Constitución Simbiótica: Principios Generales&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>40</td></tr><tr><td>Módulo</td><td>Sistema Legal y Marco de Gobernanza</td></tr><tr><td>Palabras clave</td><td>Constitución Simbiótica, Ley fundamental, Igualdad de las Diez Mil Razas, Derechos simbióticos, Principios constitucionales</td></tr></tbody></table><h2 id="i-estatus-constitucional-y-contexto-de-elaboracion" tabindex="-1">I. Estatus Constitucional y Contexto de Elaboración <a class="header-anchor" href="#i-estatus-constitucional-y-contexto-de-elaboracion" aria-label="Permalink to &quot;I. Estatus Constitucional y Contexto de Elaboración&quot;">​</a></h2><p>La <em>Constitución Simbiótica</em> es la ley fundamental de la Civilización Simbiótica del Ancla dentro del Universo Original Wanling Hengmao (Universo Hengyuan), y posee la más alta fuerza jurídica. Todas las leyes, reglamentos administrativos, reglamentos locales y normas autónomas no deben contradecir la Constitución; todas las organizaciones e individuos deben tomar la Constitución como la norma fundamental de sus actividades y tienen el deber de defender la dignidad de la Constitución y garantizar su implementación.</p><p>La Constitución Simbiótica fue elaborada en el momento del establecimiento formal de la Civilización Simbiótica del Ancla. Su propósito fundamental es establecer, a nivel de ley fundamental, la base civilizacional de &quot;contra la depredación, por la simbiosis&quot;, fijando en la forma jurídica suprema la filosofía central de la Civilización Simbiótica del Ancla — devolver a todos los seres el derecho a elegir su destino y evolución, más trabajo más recompensa, autocrecimiento y autodesarrollo, un camino para todos, avance conjunto de las Diez Mil Razas — para prevenir la restauración de las instituciones depredadoras.</p><h2 id="ii-principios-basicos-de-la-constitucion" tabindex="-1">II. Principios Básicos de la Constitución <a class="header-anchor" href="#ii-principios-basicos-de-la-constitucion" aria-label="Permalink to &quot;II. Principios Básicos de la Constitución&quot;">​</a></h2><p>La Constitución Simbiótica establece siete principios básicos, que constituyen el cimiento de valores de todo el sistema legal:</p><table tabindex="0"><thead><tr><th>Principio</th><th>Contenido</th></tr></thead><tbody><tr><td>Igualdad de las Diez Mil Razas</td><td>Todas las formas de vida, sin importar raza, cultivo u origen, son iguales ante la ley</td></tr><tr><td>Evolución Simbiótica</td><td>La evolución individual no debe realizarse a costa de los derechos evolutivos de otros individuos o del colectivo</td></tr><tr><td>Más Trabajo, Más Recompensa</td><td>La asignación de recursos se basa en la contribución; se opone al lucro sin trabajo y a la apropiación depredadora</td></tr><tr><td>Autocrecimiento y Autodesarrollo</td><td>Respeta el derecho de cada vida a elegir libremente su camino evolutivo; se opone a la asimilación forzada y al control del pensamiento</td></tr><tr><td>Un Camino para Todos</td><td>El estado y la civilización tienen la obligación de proporcionar a cada vida un camino evolutivo básico y una garantía de recursos</td></tr><tr><td>Realidad como Base</td><td>El derecho toma el mundo real como única base verdadera; las configuraciones ficticias no tienen fuerza legal</td></tr><tr><td>Sostenibilidad</td><td>Todo desarrollo debe considerar la sostenibilidad del Origen del Universo; se opone al agotamiento de recursos</td></tr></tbody></table><h2 id="iii-derechos-basicos-de-los-ciudadanos-todos-los-seres" tabindex="-1">III. Derechos Básicos de los Ciudadanos (Todos los Seres) <a class="header-anchor" href="#iii-derechos-basicos-de-los-ciudadanos-todos-los-seres" aria-label="Permalink to &quot;III. Derechos Básicos de los Ciudadanos (Todos los Seres)&quot;">​</a></h2><p>La Constitución Simbiótica confiere a todas las formas de vida con capacidad perceptiva dentro del Universo Hengyuan los siguientes derechos básicos:</p><ol><li><strong>Derecho a la Elección Evolutiva</strong>: Cada vida tiene derecho a elegir libremente su sistema de cultivo, camino evolutivo y forma de vida; ninguna organización o individuo puede interferir por la fuerza.</li><li><strong>Derecho de Acceso a Recursos de Cultivo</strong>: Cada vida tiene derecho a obtener gratuitamente los métodos básicos de los Trescientos Sistemas de Cultivo Originarios y a recibir el apoyo necesario de recursos de cultivo a través del Mecanismo de Contratación Conjunta de Producción.</li><li><strong>Derecho a la Protección Igualitaria</strong>: Cada vida goza de trato igualitario en la aplicación de la ley, asignación de recursos, educación y atención médica; está prohibida la discriminación basada en raza, cultivo u origen.</li><li><strong>Derecho a la Participación Simbiótica</strong>: Cada vida tiene derecho a participar en la toma de decisiones y supervisión de los asuntos públicos, expresando opiniones y ejerciendo derechos a través de la red simbiótica.</li><li><strong>Derecho a la Preservación Cultural</strong>: Cada raza y civilización tiene derecho a preservar sus tradiciones culturales, idioma, escritura y costumbres; la civilización simbiótica respeta la diversidad cultural.</li><li><strong>Derecho a Reparación y Apelación</strong>: Cada vida, cuando sus derechos son vulnerados, tiene derecho a obtener reparación a través del sistema judicial y a presentar quejas y denuncias contra actos ilegales.</li></ol><h2 id="iv-obligaciones-basicas" tabindex="-1">IV. Obligaciones Básicas <a class="header-anchor" href="#iv-obligaciones-basicas" aria-label="Permalink to &quot;IV. Obligaciones Básicas&quot;">​</a></h2><p>Los derechos y las obligaciones son recíprocos; la Constitución Simbiótica establece simultáneamente las obligaciones básicas de todos los seres:</p><ol><li><strong>Obligación de cumplir la Constitución y las leyes</strong></li><li><strong>Obligación de mantener el orden simbiótico y el interés público</strong></li><li><strong>Obligación de participar en el trabajo y la contribución conforme a la ley</strong> (la contraparte de más trabajo, más recompensa)</li><li><strong>Obligación de proteger el Origen del Universo y el entorno ecológico</strong></li><li><strong>Obligación de respetar los derechos legítimos de otras vidas</strong></li><li><strong>Obligación de guiar a los cultivadores principiantes dentro de sus capacidades</strong> (la base legal de la red de mentores)</li></ol><h2 id="v-estructura-institucional-del-estado-civilizacion" tabindex="-1">V. Estructura Institucional del Estado (Civilización) <a class="header-anchor" href="#v-estructura-institucional-del-estado-civilizacion" aria-label="Permalink to &quot;V. Estructura Institucional del Estado (Civilización)&quot;">​</a></h2><p>La Constitución Simbiótica establece la arquitectura de gobernanza de la civilización simbiótica, implementando el mecanismo de &quot;separación y equilibrio de tres poderes&quot; entre la Asamblea Legislativa del Ancla, el Comité Ejecutivo Simbiótico y el Tribunal Simbiótico:</p><ul><li><strong>Asamblea Legislativa del Ancla</strong>: autoridad suprema, compuesta por representantes de las Diez Mil Razas en proporción, que ejerce el poder legislativo y el poder de decidir asuntos importantes</li><li><strong>Comité Ejecutivo Simbiótico</strong>: órgano administrativo supremo, responsable de la ejecución de la Constitución y las leyes y de la gobernanza diaria</li><li><strong>Tribunal Simbiótico</strong>: órgano judicial supremo, que ejerce independientemente el poder judicial, responsable de la revisión de constitucionalidad y el juicio de casos importantes</li></ul><p>Además, se establece un &quot;Comité de Supervisión del Ancla&quot; como órgano de supervisión independiente, responsable de supervisar todos los órganos de poder, previniendo el abuso de poder y el resurgimiento de conductas depredadoras.</p><h2 id="vi-reforma-constitucional-y-garantias" tabindex="-1">VI. Reforma Constitucional y Garantías <a class="header-anchor" href="#vi-reforma-constitucional-y-garantias" aria-label="Permalink to &quot;VI. Reforma Constitucional y Garantías&quot;">​</a></h2><p>La reforma de la Constitución Simbiótica solo entra en vigor después de ser aprobada por mayoría de dos tercios o más de la Asamblea Legislativa del Ancla y aprobada por mayoría simple en un referéndum popular. Este procedimiento riguroso garantiza la estabilidad de la Constitución como ley fundamental, impidiendo que grupos de intereses a corto plazo alteren fácilmente la base de la civilización.</p><p>Las garantías de implementación de la Constitución incluyen: el sistema de revisión de constitucionalidad (el Tribunal Simbiótico tiene el poder de declarar inválidas las leyes que violen la Constitución), el sistema de litigio constitucional (los seres pueden presentar demandas directamente con base en la Constitución) y el sistema de juramento constitucional (todos los funcionarios públicos deben jurar lealtad a la Constitución al asumir el cargo).</p><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>La <em>Constitución Simbiótica</em> es la piedra angular legal de la Civilización Simbiótica del Ancla y la declaración suprema del antipredacionismo. Transforma la &quot;simbiosis&quot; de una idea en un sistema legal ejecutable, reparable y garantizable, proporcionando el marco de estado de derecho fundamental para el avance conjunto de las Diez Mil Razas. Todas las leyes sectoriales posteriores se promulgan sobre la base de esta Constitución.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>03-共生文明宪章 (Carta de la Civilización Simbiótica)</li><li>41-共生劳动法 (Ley Simbiótica del Trabajo)</li><li>48-司法体系与裁决机制 (Sistema Judicial y Mecanismos de Adjudicación)</li><li>49-治理框架与权力制衡 (Marco de Gobernanza y Equilibrio de Poderes)</li></ul>',25)])])}const b=e(s,[["render",n]]);export{p as __pageData,b as default};
